// Two variable definitions
const v1 = [300, 325, 350, 375, 400, 425, 450]
const vnh3 = OLI.random(0,6,0);
const volnh3 = v1[vnh3] .toPrecision(3);
const c1 = [1.5, 1.6, 1.7, 1.8, 1.9, 2.0];
const cnh3 = OLI.random(0,5,0);
const concnh3 = c1[cnh3] .toPrecision(3);

const v2 = [150, 160, 170, 180, 190, 200, 210, 220, 230, 240];
const vhcl = OLI.random(0,9,0);
const volhcl = v2[vhcl] .toPrecision(3);
const c2 = [1.0, 1.1, 1.2, 1.3, 1.4, 1.5];
const chcl = OLI.random(0,5,0);
const conchcl = c2[chcl] .toPrecision(3);

const molnh3 = concnh3*volnh3/1000;
const molnh3sf = molnh3 .toPrecision(3);
const molhcl = conchcl*volhcl/1000;
const molhclsf = molhcl .toPrecision(3);

const molbase = molnh3-molhcl;
const molbasesf = molbase .toPrecision(3);
const molacid = molhcl;
const molacidsf = molacid .toPrecision(3);
const ratio = molbase/molacid;
const ratiosf = ratio .toPrecision(3);

const ka = 1e-14/1.8e-5;
const pka = -Math.log10(ka);
const ph = pka + Math.log10(molbase/molacid);
const phsf = ph .toPrecision(3);

const phlow = 0.99*ph;
const phhigh = 1.01*ph;
// Expose variables to OLI
module.exports = {
  volhcl, conchcl, volnh3, concnh3, molhclsf, molnh3sf, molbasesf, molacidsf, ratiosf, ph, phsf, phlow, phhigh
};
